        els.append(txt(rx + 26, ry + 266, "  有人替班仍彻夜难眠、强烈自责，或闪过伤己/伤婴念头", size=10.2, color=BODY))
        els.append(txt(rx + 26, ry + 286, "• 行动：产检/产后门诊主动做 EPDS 量表筛查，科学干预可治", size=10.2, color=ORANGE, weight="700"))

