        els.append(_hex_ring(256, 146, 18, PURPLE_SOFT, PURPLE))
        els.append(txt(256, 150, "半乳糖", 8.9, PURPLE, "middle", weight="700"))
        els.append(txt(285, 150, "+", 11.5, GREEN, "middle", weight="700"))
