        els.append(txt(_tx(-4900), _ty(9), "耐受基因 -13910*T 几乎为 0%", 9.0, RED, "middle", weight="700"))
        els.append(txt(_tx(550), _ty(89), "北欧飙至 ~90%", 9.2, RED, "middle", weight="700"))

        # Famine/Plague trigger callout arrow around 2500–1000 BC
