            els.append(txt(374, ry + 15, f"r={r_v:.1f}", 9.5, r_col, weight="700", cls="mono"))
            els.append(txt(422, ry + 15, f"A={a_v:+.2f}", 9.5, r_col, weight="700", cls="mono"))
