        els.append(txt(650, 404, f"均值 μ={mean_r:.2f}, σ={std_r:.2f}", 9.6, SLATE, "middle"))
        els.append(txt(650, 422, "零神经奖励模型 =", 9.8, BODY, "middle"))
        els.append(txt(650, 437, "堵死长链刷分漏洞！", 9.8, GREEN, "middle", weight="700"))

