        # Log2(k) from k=1 (0) to k=128 (7)
        ks = [0, 1, 2, 3, 4, 5, 6, 7]
        # Schematic grounded in Yue et al. (arXiv:2504.13837): RLVR higher at small k, Base crosses over at large k
        y_rl_k = [42, 54, 62, 67, 70, 72, 73.5, 74.5]
