        els.append(txt(221, 135, "① 电磁振动泵 (Ulka)", 9.2, ORANGE, "middle", weight="700"))
        els.append(txt(221, 152, "220V 串二极管半波整流", 8.3, INK, "middle", weight="600"))
        els.append(txt(221, 168, "每秒往复 50 次 · 闷堵 15bar", 8.2, BODY, "middle"))

