        els.append(txt(438, 192, "• 高危必守 ≥70 °C（<2–3 月龄新生儿、早产/低体重及免疫弱宝）：", 7.7, RED, weight="700"))
        els.append(txt(438, 209, "  烧开水晾凉 ≤30 分钟（≥70°C）冲调，瞬杀耐干潜伏的阪崎克罗", 7.6, BODY))
