        els.append(txt(304, 414, "随枯叶直接丢弃不回收!", 11.5, BODY, "middle"))
        els.append(txt(304, 435, "红叶树同步泵入花青素", 11.5, CRIMSON, "middle", weight="700"))

        # Bottom Callout Banner in Left Card
