        els.append(txt(42, 451, "  蝴蝶立刻丧失集体定向；涂透明", 11.5, BODY))
        els.append(txt(42, 470, "  漆对照组则精准向南飞往墨西哥", 11.5, GREEN, weight="700"))

        # Panel B: Desert Ant Stilts & Stumps Pedometer (Wittlinger et al. 2006 Science)
