        els.append(txt(286, 448, "• 放回巢重走一趟全程穿高跷：", 11.5, BODY))
        els.append(txt(286, 468, "  去程回程步幅抵消，又精准命中！", 11.5, GREEN, weight="700"))

        # Panel C: Emlen (1970 Science) Planetarium Star Rotation Experiment
