        els.append(txt(x2 + 36, cy + 26, "桑葚：整串花序聚花果", 12.6, INK, weight="700"))
        els.append(txt(x2 + 16, cy + 46, "一粒桑葚 = 几十朵小花抱成团！", 10.2, MUTED))

