        els.append(step_badge(x3 + 20, cy + 22, "3", fg=ORANGE, bg=ORANGE_SOFT, r=10))
        els.append(txt(x3 + 36, cy + 26, "柑橘柚子：特化柑果", 12.6, INK, weight="700"))
        els.append(txt(x3 + 16, cy + 46, "一瓣一瓣的果粒竟是“内果皮长毛”！", 10.2, MUTED))

        ox, oy = x3 + 116, cy + 132
