        for nx, ny, w_box, nfill, nstroke, ntitle, nsub in nodes:
            els.append(card(nx - w_box / 2, ny - 24, w_box, 48, rx=8, fill=nfill, stroke=nstroke))
            els.append(txt(nx, ny - 5, ntitle, 8.4, nstroke, weight="700", anchor="middle"))
