        # Nuclear well + Coulomb barrier 1/r curve
        well_pts = [(wx0, wy_bot - 6), (wx_wall, wy_bot - 6), (wx_wall, 126.0)]
        for i in range(46):
            rx_c = wx_wall + i * 6.0
            vy_c = wy_zero - (116.0 * 38.0 / (38.0 + (rx_c - wx_wall)))
