        els.append(_poly(well_pts, stroke=BLUE, sw=2.6))

        # Energy level E_alpha = 4.27 MeV line at y = 212
        y_ea = 212.0
        x_exit = wx_wall + 38.0 * (116.0 / (wy_zero - y_ea) - 1.0)  # exact barrier exit!
