        # Right card: 2D regime map
        els.append(card(388, 68, 352, 412))
        els.append(pill(400, 80, "B. 云内非感应起电相图（上升速度 × 过冷水）", fg=PURPLE, bg=PURPLE_SOFT, w=292, h=22, size=11.5))

        rx0, ry0, rw, rh = 452, 136, 258, 190
